import sys
import re

def main():
    text = sys.stdin.read()
    vars_ = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;?\s*$')

    def evaluate(expr):
        # Expressions look like "(X + n) mod 100" or a plain integer.
        py = re.sub(r'\bmod\b', '%', expr)

        def repl(m):
            name = m.group(0)
            if name in vars_:
                return str(vars_[name])
            return name

        py = re.sub(r'[A-Za-z_]\w*', repl, py)
        return eval(py, {"__builtins__": {}}, {})

    for raw in text.splitlines():
        line = raw.split('//', 1)[0].strip()
        if not line:
            continue
        for stmt in line.split(';'):
            stmt = stmt.strip()
            if not stmt:
                continue
            m = assign_re.match(stmt)
            if not m:
                continue
            name, expr = m.group(1), m.group(2)
            vars_[name] = evaluate(expr)

    order = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'TMP']
    print(' '.join(f"{v} ?= {vars_.get(v, 0)};" for v in order))

if __name__ == '__main__':
    main()
